/// <summary>
/// This is an extension class for SysDocuBrandDetails table.
/// </summary>
[ExtensionOf(tableStr(SysDocuBrandDetails))]
final class SysDocuBrandDetails_Metcash_Extension
{
}

Method.Source:
    /// <summary>
    /// Find the unique SysDocuBrandDetails record based on the report name and industry key.
    /// </summary>
    /// <param name = "_repName">Report name.</param>
    /// <param name = "_indKey">Industry key.</param>
    /// <param name = "_forUpdate">ForUpdate boolean value.</param>
    /// <returns>Returns the SysDocuBrandDetails buffer based on the report name and Industry key.</returns>
    public static SysDocuBrandDetails findByRepNameAndIndKey(SrsReportName _repName, METIndustryKey _indKey, boolean _forUpdate)
    {
        SysDocuBrandDetails sysDocuBrandDetails;

        if (_repName && _indKey)
        {
            sysDocuBrandDetails.SelectForUpdate(_forUpdate);

            select firstonly sysDocuBrandDetails where
               sysDocuBrandDetails.ReportName == _repName
                && sysDocuBrandDetails.METIndustryKey == _indKey;
        }

        return sysDocuBrandDetails;
    }

    /// <summary>
    /// Validate the Industry key to be mandatory when report name entered. 
    /// </summary>
    /// <returns>Return true if validation success, Otherwise false.</returns>
    public boolean validateWrite()
    {
        boolean ret;

        ret = next validateWrite();

        if (!this.METIndustryKey && this.ReportName)
        {
            ret = checkFailed("@MET:IndustryKeMandatory");
        }
       
        return ret;
    }
